{"command": "python3 <<'PY'
import subprocess, os, tempfile
def run(args, stdin_data=None, env=None, timeout=5):
    e=dict(os.environ)
    if env is not None:
        e.update(env)
    try:
        if isinstance(stdin_data, str):
            stdin_data=stdin_data.encode()
        p=subprocess.run(["./executable"]+args, input=stdin_data, capture_output=True, timeout=timeout, env=e)
        return p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')
    except subprocess.TimeoutExpired as ex:
        out=ex.stdout.decode(errors='replace') if isinstance(ex.stdout, bytes) else str(ex.stdout)
        err=ex.stderr.decode(errors='replace') if isinstance(ex.stderr, bytes) else str(ex.stderr)
        return "TIMEOUT", out, err

for args in [["-a"], ["-c","echo"], ["-cc","echo"], ["echo","hi"], ["-n","echo"]]:
    rc,out,err=run(args, stdin_data="/tmp/nonexistent12345\n")
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:400]} ERR={repr(err)[:800]}")
    print("---")

with tempfile.NamedTemporaryFile(delete=False, mode='w') as f:
    f.write("hello")
    fname=f.name
print("fname",fname)
for args in [["echo","hi"]]:
    rc,out,err=run(args, stdin_data=fname+"\n", timeout=3)
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:800]} ERR={repr(err)[:800]}")
os.unlink(fname)
PY"}

