{"command": "python3 <<'PY'
import subprocess, os, tempfile
def run(args, stdin_data=None, env=None, timeout=5):
    e=dict(os.environ)
    if env is not None:
        e.update(env)
    # handle env deletion: if value is None, delete key
    if isinstance(stdin_data, str):
        stdin_data=stdin_data.encode()
    try:
        p=subprocess.run(["./executable"]+args, input=stdin_data, capture_output=True, timeout=timeout, env=e)
        return p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')
    except subprocess.TimeoutExpired as ex:
        return "TIMEOUT", "", ""

tmpdir=tempfile.mkdtemp()
print(tmpdir)
for mode in [0o200, 0o100, 0o444, 0o222, 0o333, 0o666, 0o777, 0o404, 0o202]:
    p=os.path.join(tmpdir,f"f{oct(mode)}"); open(p,"w").write("x"); os.chmod(p, mode)
    rc,out,err=run(["-n","-z","echo","hi"], stdin_data=p+"\n", timeout=3)
    print(f"mode {oct(mode)} RC={rc} ERR={repr(err)[:200]}")

# test FOLLOW values
reg=os.path.join(tmpdir,"reg"); open(reg,"w").write("x")
broken=os.path.join(tmpdir,"broken2"); 
try: os.symlink("/nope2", broken)
except: pass
for val in ["", "0", "1", "false", "TRUE"]:
    # need to set env exactly; for "" need to include empty
    import subprocess as sp, os as _os
    e=dict(_os.environ); e["ENTR_FOLLOW_SYMLINK"]=val
    pp=sp.run(["./executable","-n","-z","echo","hi"], input=(broken+"\n").encode(), capture_output=True, timeout=3, env=e)
    print(f"FOLLOW={repr(val)} RC={pp.returncode} ERR={repr(pp.stderr.decode()[:200])}")
# unset
rc,out,err=run(["-n","-z","echo","hi"], stdin_data=broken+"\n", timeout=3)
print(f"FOLLOW unset RC={rc} ERR={repr(err)[:200]}")
# test with FOLLOW and symlink to dir/file still works
import shutil; shutil.rmtree(tmpdir)
PY"}

