import subprocess, os, tempfile, time
def run(args, stdin_data=None, env=None, timeout=5):
    e=dict(os.environ)
    if env is not None:
        e.update(env)
    if isinstance(stdin_data, str):
        stdin_data=stdin_data.encode()
    try:
        p=subprocess.run(["./executable"]+args, input=stdin_data, capture_output=True, timeout=timeout, env=e)
        return p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')
    except subprocess.TimeoutExpired as ex:
        out=ex.stdout.decode(errors='replace') if isinstance(ex.stdout, bytes) else ""
        err=ex.stderr.decode(errors='replace') if isinstance(ex.stderr, bytes) else ""
        return "TIMEOUT", out, err

tmpdir=tempfile.mkdtemp()
f1=os.path.join(tmpdir,"f1.txt"); open(f1,"w").write("hello")
f2=os.path.join(tmpdir,"f2.txt"); open(f2,"w").write("world")

# /_ substitution
for args in [["-n","-z","echo","/_"], ["-n","-z","echo","prefix/_suffix"], ["-n","-z","echo","/_","/_"], ["-n","-z","echo","hi"]]:
    rc,out,err=run(args, stdin_data=f1+"\n"+f2+"\n", timeout=3)
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:300]} ERR={repr(err)[:300]}")

# -s tests
for args in [["-n","-z","-s","echo hi"], ["-n","-z","-s","echo $0"], ["-n","-z","-s","echo hi; echo bye"]]:
    rc,out,err=run(args, stdin_data=f1+"\n", timeout=3)
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:500]} ERR={repr(err)[:500]}")

# -s with /_ ? man says $0 is filename when -s used
for args in [["-n","-z","-s","echo /_"]]:
    rc,out,err=run(args, stdin_data=f1+"\n", timeout=3)
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:500]} ERR={repr(err)[:500]}")

# -c tests: need to capture clear sequences
for args in [["-n","-z","-c","echo","hi"], ["-n","-z","-cc","echo","hi"]]:
    rc,out,err=run(args, stdin_data=f1+"\n", timeout=3)
    print(f"ARGS={args} RC={rc} OUT={repr(out)[:1000]} ERR={repr(err)[:500]}")

# -z exit status
for cmd in [["false"], ["sh","-c","exit 3"], ["sh","-c","kill -TERM $$"], ["nonexistent_cmd_xyz"]]:
    rc,out,err=run(["-n","-z"]+cmd, stdin_data=f1+"\n", timeout=3)
    print(f"CMD={cmd} RC={rc} OUT={repr(out)[:300]} ERR={repr(err)[:600]}")

import shutil; shutil.rmtree(tmpdir)
PY"}

