import subprocess as sp, os, tempfile, time, threading
def run_once(exe, args, inp, timeout=3, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    try:
        p=sp.run([exe]+args, input=inp.encode(), capture_output=True, timeout=timeout, env=e)
        return p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')
    except sp.TimeoutExpired:
        return "TIMEOUT", "", ""
